<script setup>
import { ref, computed } from 'vue'

const props = defineProps({
    servicesData: Object
})

const search = ref('')

// Удаление HTML тегов
const stripHtml = (html) => {
    return html?.replace(/<[^>]*>/g, '') || ''
}

// Преобразуем в массив
const servicesList = Object.keys(props.servicesData).map(key => ({
    key,
    ...props.servicesData[key]
}))

const filteredServices = computed(() => {
    const query = search.value.trim().toLowerCase()

    // 👉 если пусто → популярное
    if (!query) {
        return servicesList.slice(0, 6)
    }

    const result = servicesList.filter(item => {
        const key = item.key.toLowerCase()
        const title = item.title?.toLowerCase() || ''
        const description = stripHtml(item.description).toLowerCase()

        return (
            key.includes(query) ||
            title.includes(query) ||
            description.includes(query)
        )
    })

    return result.slice(0, 6)
})

// 👉 состояние
const isSearching = computed(() => !!search.value.trim())

const hasResults = computed(() => filteredServices.value.length > 0)

// 👉 заголовок
const titleText = computed(() => {
    if (!isSearching.value) return 'Популярное на сайте'
    if (hasResults.value) return 'Найдено на сайте'
    return 'Ничего не найдено'
})
</script>